static_assert(JOINT_COUNT == arm::kJointCount, "config.h and arm_core disagree on joints");

namespace {

constexpr uint32_t kPulseNs = 200;     // STEP high time; TMC5160/2209 need about 100 ns
constexpr long kMaxSpinRate = 20000;   // steps/s; SPIN has no acceleration, keep it slow
constexpr long kDefaultSpinRate = 400;

// Each driver's STEP and DIR pins as GPIO register + bit, so the interrupt can set them
// with one store instead of digitalWrite().
struct FastPin {
  GPIO_TypeDef* port;
  uint32_t bit;
};
FastPin stepPins[kDriverCount];
FastPin dirPins[kDriverCount];

FastPin fastPin(uint32_t pin) {
  return {digitalPinToPort(pin), STM_GPIO_PIN(digitalPinToPinName(pin))};
}

inline void setPin(const FastPin& p) { p.port->BSRR = p.bit; }
inline void clearPin(const FastPin& p) { p.port->BSRR = p.bit << 16; }

// drivers::configureAll() prints to an Arduino Print; this forwards to an arm::Output.
class OutputPrint : public Print {
 public:
  explicit OutputPrint(arm::Output& out) : out_(out) {}
  size_t write(uint8_t c) override {
    char ch = static_cast<char>(c);
    out_.write(&ch, 1);
    return 1;
  }
  size_t write(const uint8_t* buffer, size_t size) override {
    out_.write(reinterpret_cast<const char*>(buffer), size);
    return size;
  }

 private:
  arm::Output& out_;
};

int parseJoint(const char* name) {
  for (int j = 0; j < JOINT_COUNT; ++j) {
    if (strcmp(name, kJoints[j].name) == 0) {
      return j;
    }
  }
  return -1;
}

const char* const kHelp =
    "Protocol commands (docs/control_system_decisions.md, section 4):\n"
    "  HELLO, LIMITS <joint> <min> <max> <max_rate>, ENABLE, DISABLE, HOME,\n"
    "  SETPOS <5 steps>, SEG <dur_us> <5 steps>, GO, END, STOP, STATUS, CLEAR, PING\n"
    "Bring-up commands (IDLE only):\n"
    "  INFO                         firmware version, CPU clock, and the longest step\n"
    "                               interrupt since boot (tick_max) vs its budget\n"
    "  DRIVERS                      configure all drivers and check they answer\n"
    "                               (needs motor power; run again after it's cycled)\n"
    "  SPIN <joint> <steps> [rate]  move one joint at a constant rate (default 400\n"
    "                               steps/s); ENABLE first. Any input aborts.\n"
    "  ENDSTOPS                     raw endstop input levels\n"
    "Joints: THETA Z R YAW PITCH. A leading number is the sequence number (optional).\n";

}  // namespace

void OctopusHal::begin() {
  for (size_t d = 0; d < kDriverCount; ++d) {
    const board::DriverSlotPins& p = board::kSlotPins[kDrivers[d].slot];
    stepPins[d] = fastPin(p.step);
    dirPins[d] = fastPin(p.dir);
  }
  // The cycle counter times the step pulse.
  CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
  DWT->CYCCNT = 0;
  DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
  pulseCycles_ = SystemCoreClock / 1000000 * kPulseNs / 1000;
}

void OctopusHal::setDirection(int joint, bool forward) {
  for (size_t d = 0; d < kDriverCount; ++d) {
    if (kDrivers[d].joint == joint) {
      if (forward != kDrivers[d].invert_dir) {
        setPin(dirPins[d]);
      } else {
        clearPin(dirPins[d]);
      }
    }
  }
}

void OctopusHal::stepPulse(uint32_t mask) {
  for (size_t d = 0; d < kDriverCount; ++d) {
    if (mask & (1U << kDrivers[d].joint)) {
      setPin(stepPins[d]);
    }
  }
  uint32_t start = DWT->CYCCNT;
  while (DWT->CYCCNT - start < pulseCycles_) {
  }
  for (size_t d = 0; d < kDriverCount; ++d) {
    if (mask & (1U << kDrivers[d].joint)) {
      clearPin(stepPins[d]);
    }
  }
}

void OctopusHal::setEnabled(bool on) {
  for (size_t d = 0; d < kDriverCount; ++d) {
    drivers::setEnabled(d, on);
  }
}

arm::ExtraResult OctopusHal::extraCommand(const char* seq, uint32_t freeSlots,
                                          const char* command, int argc, char** argv,
                                          arm::Output& out) {
  unsigned long q = freeSlots;
  if (strcmp(command, "HELP") == 0) {
    out.print(kHelp);
    out.printf("%s OK q=%lu\n", seq, q);
  } else if (strcmp(command, "INFO") == 0) {
    out.printf("%s OK q=%lu firmware=%s sysclk=%lu tick_max=%lu tick_budget=%lu\n", seq, q,
               arm::kFirmwareVersion, static_cast<unsigned long>(HAL_RCC_GetSysClockFreq()),
               static_cast<unsigned long>(tickMaxCycles_),
               static_cast<unsigned long>(SystemCoreClock / arm::kTickHz));
  } else if (strcmp(command, "DRIVERS") == 0) {
    OutputPrint print(out);
    if (drivers::configureAll(print)) {
      out.printf("%s OK q=%lu all drivers answered\n", seq, q);
    } else {
      out.printf("%s ERR NO_ANSWER q=%lu some drivers did not answer\n", seq, q);
    }
  } else if (strcmp(command, "ENDSTOPS") == 0) {
    out.printf("%s OK q=%lu", seq, q);
    for (const JointConfig& j : kJoints) {
      out.printf(" %s=%d", j.name, digitalRead(board::kEndstopPins[j.endstop]));
    }
    out.print("\n");
  } else if (strcmp(command, "SPIN") == 0) {
    return spin(seq, q, argc, argv, out);
  } else {
    return arm::ExtraResult::kUnknown;
  }
  return arm::ExtraResult::kDone;
}

// Bring-up only: blocking, constant speed, no acceleration. Moves the motor outside the
// step generator, so the board forgets its position (homed=0).
arm::ExtraResult OctopusHal::spin(const char* seq, unsigned long q, int argc, char** argv,
                                  arm::Output& out) {
  int joint = argc >= 2 ? parseJoint(argv[0]) : -1;
  if (joint < 0) {
    out.printf("%s ERR BAD_ARGS q=%lu SPIN <joint> <steps> [rate]\n", seq, q);
    return arm::ExtraResult::kDone;
  }
  long steps = strtol(argv[1], nullptr, 10);
  long rate = argc >= 3 ? strtol(argv[2], nullptr, 10) : kDefaultSpinRate;
  if (rate <= 0 || rate > kMaxSpinRate) {
    out.printf("%s ERR BAD_ARGS q=%lu rate must be 1..%ld steps/s\n", seq, q, kMaxSpinRate);
    return arm::ExtraResult::kDone;
  }
  for (size_t d = 0; d < kDriverCount; ++d) {
    if (kDrivers[d].joint == joint && !drivers::isEnabled(d)) {
      out.printf("%s ERR DISABLED q=%lu ENABLE first\n", seq, q);
      return arm::ExtraResult::kDone;
    }
  }

  setDirection(joint, steps >= 0);
  delayMicroseconds(5);  // direction setup time before the first step
  long total = labs(steps);
  uint32_t interval = 1000000UL / rate;
  uint32_t next = micros();
  long done = 0;
  for (; done < total && !Serial.available(); ++done) {
    while (static_cast<int32_t>(micros() - next) < 0) {
    }
    next += interval;
    stepPulse(1U << joint);
  }
  if (done < total) {
    out.printf("%s ERR ABORTED q=%lu after %ld of %ld steps\n", seq, q, done, total);
  } else {
    out.printf("%s OK q=%lu %s moved %ld steps\n", seq, q, kJoints[joint].name, steps);
  }
  return arm::ExtraResult::kDoneMoved;
}
